/**
 * Phase 4.5D — bundled scene assets for the renderer.
 *
 * `scenes.bundle.json` is generated by `pnpm build-scenes` from the
 * authored assets under `modernization/scenes/`. Imported directly
 * (resolveJsonModule) so the browser never needs `node:fs`.
 *
 * `SCENES_BY_LOCATION` is the index `selectScene` consumes. The index
 * is built inline (not via the scene barrel's `indexScenesByLocation`)
 * so the loader's `node:fs` import never enters the browser bundle.
 */

import type { SceneAsset } from "../../../modernization/runtime/scene/index.js";
import bundle from "./scenes.bundle.json";

export const BUNDLED_SCENES: SceneAsset[] = bundle as SceneAsset[];

export const SCENES_BY_LOCATION: Record<string, SceneAsset> = BUNDLED_SCENES.reduce(
  (acc, scene) => {
    acc[scene.location] = scene;
    return acc;
  },
  {} as Record<string, SceneAsset>,
);
